import copy
from support import ROOT, LAB, PREVIOUS, L1, PACKAGE, load, dump, sha, binding, module
TEXT={'type':'string','pattern':r'\S'}
def obj(p): return {'type':'object','additionalProperties':False,'required':sorted(p),'properties':p}
def array(item,minimum=1): return {'type':'array','minItems':minimum,'maxItems':100,'items':item}
def build():
    ref=obj({'path':TEXT,'sha256':{'type':'string','pattern':'^[0-9a-f]{64}$'}})
    contract=obj({'schema_version':{'const':'cal-discipline-record/v1'},'artifact_type_ref':{'const':'cal.artifact-type.discipline/v1'},'discipline_id':TEXT,'status':{'const':'candidate-unadmitted'},'authority_effect':{'const':'none'},'practice':TEXT,'scope_ref':TEXT,'steward_ref':TEXT,'maturity_status':{'const':'candidate'},'governance_route_ref':TEXT,'capabilities':array(obj({'capability_ref':TEXT,'artifact':ref}),2),'recurrence_evidence':array(obj({'occurrence_id':TEXT,'capability_ref':TEXT,'receipt':ref}),2),'evidence_profile':{'const':'candidate:validation-material-map/v1'},'hardening_move':obj({'owner_ref':TEXT,'route_ref':TEXT,'action':TEXT,'completion_evidence_required':TEXT}),'boundaries':TEXT,'source_direction':obj({'canonical':{'const':'discipline-record.json'},'human_projection':{'const':'DISCIPLINE.md'},'projection_policy':{'const':'generated-only'}}),'claim_ceiling':TEXT})
    contract['$schema']='https://json-schema.org/draft/2020-12/schema'
    dump(PACKAGE/'schema.json',contract); dump(ROOT/'contracts.json',{'authority_effect':'none','schemas':[binding(PACKAGE/'schema.json')]})
    batches=[('schema','0009-schema-carrier'),('method','0011-method-carrier')]
    example={'schema_version':'cal-discipline-record/v1','artifact_type_ref':'cal.artifact-type.discipline/v1','discipline_id':'CANDIDATE-REPOSITORY-STEWARDSHIP-001','status':'candidate-unadmitted','authority_effect':'none','practice':'Keep reconstructed repository surfaces traceable, validated and resumable through exact validation records.','scope_ref':'scope:lab-reconstruction-stewardship','steward_ref':'role:repository-steward','maturity_status':'candidate','governance_route_ref':'route:discipline-governance','capabilities':[{'capability_ref':'capability:'+name,'artifact':binding(ROOT.parent/batch/f'artifact-types/{name}/v1/artifact.json')} for name,batch in batches],'recurrence_evidence':[{'occurrence_id':'validation:'+name,'capability_ref':'capability:'+name,'receipt':binding(ROOT.parent/batch/'receipts/validation.json')} for name,batch in batches],'evidence_profile':'candidate:validation-material-map/v1','hardening_move':{'owner_ref':'role:repository-steward','route_ref':'route:repository-maintenance-review','action':'Review coverage of source tracing and validation across remaining capabilities, then record missing checks and owners.','completion_evidence_required':'An exact review record covering the remaining capability inventory and every unresolved obligation.'},'boundaries':'Evidence supports repeated local validation only. It does not prove continuous stewardship or grant definition, constitution, implementation or promotion authority.','source_direction':{'canonical':'discipline-record.json','human_projection':'DISCIPLINE.md','projection_policy':'generated-only'},'claim_ceiling':'Candidate stewardship declaration with exact local validation evidence only; no automatic maturity promotion or hardening completion.'}
    artifact=load(PREVIOUS/'artifact-types/method/v1/artifact.json'); path=L1/'definitions/discipline/v1/definition.json'; definition=load(path)
    bound={**binding(path),'definition_ref':definition['definition_id']+'@'+definition['version'],'admission_posture':'candidate-unadmitted'}
    artifact.update(artifact_type_id='cal.artifact-type.discipline',artifact_type_ref='cal.artifact-type.discipline/v1',name='Discipline',schema_ref='cal.schema.discipline-carrier/v1',schema_digest=sha(PACKAGE/'schema.json'),semantic_definition_refs=[bound['definition_ref']],semantic_definition_bindings=[bound],distinct_validation_purpose='Defines a stewarded recurring cross-capability practice.')
    artifact['classification'].update(semantic_kind='discipline',lifecycle_posture_ref='candidate:discipline-reconstruction/v1')
    artifact['instance_contract'].update(canonical_filename='discipline-record.json',human_filename='DISCIPLINE.md',identity_field='discipline_id',required_semantic_fields=sorted(set(contract['required'])-{'schema_version','status','authority_effect','source_direction','claim_ceiling'}))
    artifact['orthogonality_rules']=[{'rule_id':'DISCIPLINE-01','statement':'Distinct occurrence evidence must cover distinct capabilities and bind their checked artifacts.'},{'rule_id':'DISCIPLINE-02','statement':'Recurrence never automatically promotes maturity or grants authority.'}]
    artifact['four_facets']={'classification':'Candidate Discipline bound to source-qualified D50 and stewardship source D6.','schema':'Steward, recurring practice, capability evidence, candidate maturity and hardening route.','machine_checkable':'Unique occurrences, distinct capability artifacts, exact receipt material closure and passing checks.','human_continuation':'Generated DISCIPLINE.md names the practice, evidence limits and next improvement.'}
    artifact['typed_residue']=[{'residue_id':'DISCIPLINE-R1','owner_ref':'role:repository-steward','missing':'Owner admission, maturity-transition rules and evidence of sustained practice.','consequence':'Only candidate maturity is supported; recurrence does not authorize promotion.'}]; artifact['claim_ceiling']=example['claim_ceiling']
    invalid={}
    for name,key,val in [('authority','authority_effect','promote'),('canonical','maturity_status','canonical'),('active-pattern','maturity_status','active-pattern'),('empty-evidence','recurrence_evidence',[]),('blank-steward','steward_ref',' '),('extra-field','promoted',True),('unknown-profile','evidence_profile','trust-labels')]:
        bad=copy.deepcopy(example); bad[key]=val; invalid[name]=bad
    bad=copy.deepcopy(example); bad['hardening_move']['route_ref']=' '; invalid['missing-route']=bad
    artifact['validation_contract'].update(positive_witness='fixtures/valid/discipline-record.json',positive_projection='fixtures/valid/DISCIPLINE.md',negative_witnesses=['fixtures/invalid/'+x+'.json' for x in sorted(invalid)],validator_path=str((ROOT/'validate.py').relative_to(LAB)))
    dump(PACKAGE/'artifact.json',artifact); dump(PACKAGE/'fixtures/valid/discipline-record.json',example)
    for name,bad in invalid.items(): dump(PACKAGE/f'fixtures/invalid/{name}.json',bad)
    renderer=module(LAB/'tooling/generators/artifact_surface.py','discipline_renderer'); artifact=load(PACKAGE/'artifact.json')
    (PACKAGE/'ARTIFACT.md').write_text(renderer.render_artifact(artifact)); (PACKAGE/'fixtures/valid/DISCIPLINE.md').write_text(renderer.render_instance(artifact,load(PACKAGE/'fixtures/valid/discipline-record.json')))
    dump(ROOT/'registry.json',{'authority_effect':'none','entries':[{'target_id':'type.discipline','family':'artifact-type','status':'candidate-unadmitted',**binding(PACKAGE/'artifact.json')}]})
    selected={'semantic.discipline'}; edges=load(L1/'batches.json')['edges']
    while True:
        expanded=selected|{x['dependency_target_id'] for x in edges if x['consumer_target_id'] in selected}
        if expanded==selected: break
        selected=expanded
    registry={x['target_id']:x for x in load(L1/'registry.json')['entries']}; scaffold=ROOT.parent/'0003-review-led-reconstruction/target-candidates/artifact-type/type-discipline/v1/artifact.json'
    dump(ROOT/'dependencies.json',{'authority_effect':'none','seed_targets':['semantic.discipline'],'inputs':[binding(PREVIOUS/'manifest.json'),binding(L1/'batches.json'),binding(scaffold)],'definitions':[{'target_id':x,**binding(LAB/registry[x]['path'])} for x in sorted(selected)],'selected_source_sections':load(scaffold)['source_refs'],'source_lineage_residue':[x for x in load(L1/'drift-audit.json')['legacy_reference_residue'] if x['consumer_target_id'] in selected]})
if __name__=='__main__': build()
